        return (
            <div className='mx_SettingsTab_section mx_HelpUserSettingsTab_versions'>
                <span className='mx_SettingsTab_subheading'>{ _t("Legal") }</span>
                <div className='mx_SettingsTab_subsectionText'>
                    { legalLinks }
                </div>
            </div>
        );
    }

